html:
{% set letter_head=frappe.get_doc("Letter Head","PawPass Letter Head")%}
<style> 
@page { 
    size: A4; 
    margin: 1cm; 
} 

.shop-name { 
    font-size: 28px; 
    font-weight: bold; 
    text-align: center; 
    margin-bottom: 5px; 
} 
 
.stay-card { 
    text-align: center; 
} 
 
.print-summary { 
    text-align: center; 
    font-size: 13px; 
    margin: 10px 0 20px 0; 
    font-weight: bold; 
} 
 
h2 { 
    text-align: center; 
    margin-bottom: 5px; 
} 
 
.final-amount { 
    font-size: 24px; 
    font-weight: bold; 
    text-align: right; 
} 

table {
    width: 100%;
    margin-bottom: 15px;
}

td, th {
    padding: 5px;
    text-align: left;
}

.letter-head img{
    max-height: 80px;
    max-width: 200px;
}
.letter-footer{
    text-align: center;
    margin-top: 35px;
    padding-top: 10px;
}
</style> 

<div class="letter-head">
    {{letter_head.content}}
</div>

<div class="shop-name"> 
    {{ get_shop_name() }} 
</div> 
 
<h2>Stay Receipt</h2> 
 
<p class="stay-card"> 
    {{ doc.name }} 
</p> 
 
<div class="print-summary"> 
    {{ doc.print_summary or "" }} 
</div> 


<div> 
    <h3>Pet & Owner Details</h3> 
 
    <table> 

        <tr> 
            <td><strong>Pet</strong></td> 
            <td>{{ doc.pet }}</td> 
        </tr> 
 
        <tr> 
            <td><strong>Owner Name</strong></td> 
            <td>{{ doc.owner_name or "-" }}</td> 
        </tr> 
 
        <tr> 
            <td><strong>Owner Phone</strong></td> 
            <td>{{ doc.owner_phone or "-" }}</td> 
        </tr> 
        
        <tr> 
            <td><strong>Check-in Date</strong></td> 
            <td>{{ doc.checkin_date or "-" }}</td> 
        </tr>
        
        <tr> 
            <td><strong>Expected Checkout</strong></td> 
            <td>{{ doc.expected_checkout_date or "-" }}</td> 
        </tr>
        
        <tr> 
            <td><strong>Purpose</strong></td> 
            <td>{{ doc.purpose or "-" }}</td> 
        </tr>
    </table> 
</div> 

<h3>Services</h3> 

<table> 
    <thead> 
        <tr> 
            <th>Service</th> 
            <th>Quantity</th> 
            <th>Rate</th> 
            <th>Total</th> 
        </tr> 
    </thead> 

    <tbody> 
        {% for row in doc.service_lines %} 
        <tr> 
            <td>{{ row.service_type }}</td> 
            <td>{{ row.quantity }}</td> 
            <td>{{ row.rate }}</td> 
            <td>{{ row.line_total }}</td> 
        </tr> 
        {% endfor %} 
    </tbody> 
</table> 


<table> 
    <tr> 
        <td>
            <strong>Services Total</strong>
        </td> 
        <td>
            {{ doc.services_total or 0 }}
        </td> 
    </tr> 
</table> 


<div class="final-amount"> 
    <strong> 
        Final Amount: 
        {{ frappe.utils.fmt_money(doc.final_amount or 0, currency="INR") }} 
    </strong> 
</div> 

<div class="letter-footer">
    {{letter_head.footer}}
</div>
